"""Explain manual write/atomic checks and pre-copy source instrumentation."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1681': ('상자에 쓰기 전에 주소와 작업 종류를 점검 담당자에게 알려 줄 수 있어요. 점검 요청을 하는 도우미와 실제 상자에 쓰는 동작을 구별해요.', '쓰기 계측의 크기·방향과 반환값 처리 방식을 이해합니다.', '주소 P의 4바이트에 쓴다고 가정하세요. KASAN write(P,4) → KCSAN write(P,4) → 실제 쓰기를 그리세요.', ['instrument_write는 실제 쓰기를 하기 전에 넣는 검사 연결 도우미예요. v는 쓸 대상 주소, size는 접근할 바이트 수예요. 주소와 크기를 실제 쓰기 범위에 맞춰 전달해야 해요.', '예를 들어 4바이트 칸에 값을 쓸 예정이면 그 칸의 주소와 4를 알려요. size가 4라는 말은 참조가 네 개라는 뜻이나 네 번 반복해서 쓰라는 뜻이 아니에요. 검사할 범위의 길이예요.', '본문은 kasan_check_write를 부른 뒤 kcsan_check_write를 불러요. KASAN은 주소·범위의 유효성 문제를, KCSAN은 동시 쓰기와 관련된 충돌을 살펴요. 같은 주소라도 read와 write가 전달하는 접근 성질은 달라요.', 'KASAN 검사 함수에는 bool, 즉 참·거짓 반환값이 있지만 이 wrapper는 그 값을 if로 검사하지 않아요. false가 돌아왔다는 이유로 다음 호출을 건너뛰는 분기가 본문에 없어요. wrapper는 다른 기능을 묶어 연결하는 코드예요.', '따라서 검사 함수가 정상적으로 돌아오면 다음 KCSAN 호출로 이어지는 코드 구조예요. 실제 검사 엔진은 오류 보고 설정에 따라 실행을 중단할 수도 있으므로, 어떤 실제 오류에서도 프로그램이 반드시 계속된다고 넓혀 말하면 안 돼요.', '이 함수의 반환형 void는 호출자에게 결과 값을 돌려주지 않는다는 뜻이에요. 대상 값을 실제로 바꾸거나 쓰기를 허가·거부하는 판정값을 돌려주는 함수가 아니에요. 실제 데이터 쓰기와 보호 규칙은 바깥의 원래 코드가 담당해요.'], [('instrument_write 본문은 KASAN의 bool 결과를 검사해 KCSAN 호출을 막나요?', ['네. false이면 return하는 분기가 있어요', '아니요. 두 호출을 차례로 적었고 bool 분기가 없어요'], '정답은 두 번째예요. 본문은 kasan_check_write 다음 kcsan_check_write예요. 실제 검사 엔진의 오류 처리 정책과 이 wrapper에 조건 분기가 있는지는 구별해야 해요.'), ('이 wrapper의 size는 무엇을 뜻하나요?', ['대상 쓰기의 바이트 수예요', '공유 객체를 사용하는 참조 수예요'], '정답은 첫 번째예요. size는 접근 범위의 크기예요. 실제 쓰려는 주소와 길이, 쓰기라는 방향이 검사 요청과 맞아야 해요.')]), 'os1682': ('하나의 작업을 두 점검 담당자에게 알릴 때 각자가 필요한 분류가 다를 수 있어요. 읽고 고쳐 쓰는 작업도 두 도구에 같은 이름으로 전달되지는 않아요.', '복합 접근의 두 검사 호출과 플래그 3을 이해합니다.', 'KASAN: write 검사 / KCSAN: read-write 검사로 두 칸을 그리고 WRITE=1 | COMPOUND=2 = 3을 적으세요.', ['read-write는 값을 읽고 바꾼 뒤 다시 쓰는 복합 접근을 뜻해요. 예를 들어 5를 읽고 1을 더해서 6을 쓰는 흐름이 있어요. 이 수업의 instrument_read_write는 그 접근을 검사 도구에 알리는 도우미예요.', '본문의 첫 호출은 kasan_check_write(v, size)예요. 함수 이름에 read_write가 들어 있다고 KASAN read와 write를 각각 한 번씩 호출하는 구조는 아니에요. 실제 본문에서 어떤 이름을 부르는지 확인해야 해요.', '두 번째 호출은 kcsan_check_read_write(v, size)예요. KCSAN에는 읽기·쓰기 복합 접근이라는 성질을 알려요. 단순 읽기 검사 두 번으로 대체한 코드도 아니에요.', '일반 read-write의 type은 WRITE와 COMPOUND를 OR한 값이에요. WRITE=001, COMPOUND=010이므로 001 | 010 = 011, 십진수로 3이에요. 읽기 전용 0이나 원자적 표시 4와 달라요.', 'KASAN과 KCSAN이 받는 분류가 다른 것은 각 도구가 검사하는 질문이 다르기 때문이에요. 주소 범위에 쓰는 접근과 동시 실행에서 읽고 수정해 쓰는 성질을 각각 알리는 구조로 이해하세요.', '이 두 호출을 했다고 일반 읽기와 쓰기가 원자적 갱신으로 바뀌지는 않아요. 두 작업이 동시에 5를 읽어 각각 6을 쓰는 문제는 실제 동기화로 해결해야 해요. 검사 표시는 데이터 접근을 대신 수행하거나 잠금을 획득하지 않아요.'], [('instrument_read_write가 KASAN에 호출하는 것은 무엇인가요?', ['read와 write 두 검사 함수를 모두 호출해요', 'write 검사 하나예요'], '정답은 두 번째예요. 원문은 kasan_check_write 한 번과 kcsan_check_read_write 한 번이에요. 바깥 이름만 보고 각 검사 도구의 호출 횟수를 추측하지 마세요.'), ('KCSAN에 전달하는 일반 복합 접근 type은 무엇인가요?', ['COMPOUND와 WRITE를 합친 3이에요', '읽기 전용인 0이에요'], '정답은 첫 번째예요. 두 비트 2와 1을 OR하면 3이에요. 읽고 쓰는 성질을 나타내지만 이 표시가 실제 CPU 원자성을 만드는 것은 아니에요.')]), 'os1683': ('아무리 한 번에 처리하는 작업이어도 이미 철거된 창고에 물건을 넣을 수는 없어요. 원자적이라는 성질과 주소가 유효하다는 조건은 달라요.', '원자적 접근에서도 KASAN 검사가 필요한 이유를 이해합니다.', 'atomic read: KASAN read·KCSAN 4 / write: KASAN write·KCSAN 5 / read-write: KASAN write·KCSAN 7을 적으세요.', ['원자적 접근은 정해진 연산이 중간에 쪼개져 관찰되지 않도록 하는 성질과 관련돼요. 그렇다고 대상 메모리의 주소와 범위가 자동으로 올바른 것은 아니에요. 이미 해제된 객체에 원자 연산을 하려 해도 대상 수명 문제가 남아요.', '그래서 instrument_atomic_read는 KASAN read 검사와 KCSAN atomic read 검사를 연결해요. instrument_atomic_write는 KASAN write와 KCSAN atomic write를 연결해요. 두 종류의 검사 질문을 함께 알리는 것이에요.', 'instrument_atomic_read_write는 kasan_check_write 뒤 kcsan_check_atomic_read_write를 호출해요. 읽고 바꾸어 쓰는 복합 접근도 실제 쓰기 대상 주소가 유효해야 하므로 KASAN 경로가 있어요.', 'KCSAN의 원자적 읽기 표시는 4, 쓰기는 4 | 1 = 5, 읽기·쓰기는 4 | 1 | 2 = 7이에요. 4는 ATOMIC, 1은 WRITE, 2는 COMPOUND라는 서로 다른 비트 칸이에요.', 'CONFIG_KCSAN_IGNORE_ATOMICS는 KCSAN의 원자적 검사 매크로를 빈 코드로 만들어요. 그러나 별도로 적혀 있는 KASAN 호출은 그 도구의 설정을 따라요. KCSAN에서 무시한다고 KASAN도 반드시 꺼지는 것은 아니에요.', '또 바깥 instrument_atomic_*는 함수이므로 그 호출의 인자 평가는 C 규칙을 따라요. 안쪽 빈 매크로가 바깥 인자의 모든 효과까지 지우는 것은 아니에요. 실제 원자 연산은 이 계측 뒤에 별도로 수행되며 그 연산의 순서·수명 규칙을 지켜야 해요.'], [('KCSAN이 원자적 접근 검사를 무시하면 KASAN 주소 검사도 반드시 없어지나요?', ['네. 모든 종류의 계측을 함께 꺼요', '아니요. 두 검사 도구의 경로는 별개예요'], '정답은 두 번째예요. IGNORE_ATOMICS는 KCSAN 쪽 매크로를 비워요. 바깥 함수에 별도로 있는 KASAN 호출은 KASAN의 조건에 따라 동작해요.'), ('atomic read-write wrapper는 KASAN에 어떤 방향의 검사를 요청하나요?', ['write 검사예요', '주소 검사는 전혀 없어요'], '정답은 첫 번째예요. 본문에는 kasan_check_write가 있어요. 원자적 갱신도 유효한 대상에 이루어져야 하므로 주소 검사와 원자성 분류를 구별하세요.')]), 'os1684': ('창고에서 손님에게 물건을 보낼 때 창고의 어느 선반에서 꺼내는지 먼저 확인해요. 배송 전 요청서에 남은 양 0이라고 적었다고 배송 완료가 증명되지는 않아요.', 'copy-out의 검사 대상 주소와 전달한 left=0의 의미를 이해합니다.', '커널 from → 사용자 to 화살표를 그리세요. 검사 대상은 from이고, KMSAN 인자는 n과 0이라고 적되 실제 복사 결과와 분리하세요.', ['copy-out은 여기서 커널 데이터가 사용자 공간으로 나가는 복사를 뜻해요. from은 커널의 원본 주소이고 to는 사용자 쪽 목적지예요. 이 방향을 먼저 그리면 어느 주소를 검사하는지 이해하기 쉬워요.', 'instrument_copy_to_user는 먼저 kasan_check_read(from, n)을 호출하고 kcsan_check_read(from, n)을 호출해요. 커널 원본에서 n바이트를 읽는 접근을 알리는 것이에요. 사용자 목적지를 이 두 커널 write 검사에 넣는 구조가 아니에요.', '그 다음 kmsan_copy_to_user(to, from, n, 0)을 호출해요. 이 wrapper는 실제 접근 전에 넣도록 문서화돼 있어요. 따라서 마지막 0은 실제 복사 함수가 돌려준 남은 길이를 받은 것이 아니라 여기서 정해 전달하는 인자예요.', 'n이 8이면 이 KMSAN 요청은 길이 8과 left 0을 보내므로 사용자 검사 경로는 요청한 8바이트를 대상으로 삼아요. 하지만 그때 이미 실제로 8바이트를 전송했다고 주장할 수는 없어요. 실제 복사는 바깥 코드가 수행하고 결과도 따로 확인해야 해요.', '앞서 본 kmsan_copy_to_user의 구현 주석은 복사 후 남은 길이를 받는 경우를 설명했어요. 이 호출자는 같은 함수를 복사 전 left=0으로도 연결해요. 그래서 함수 이름이나 내부 주석만으로 모든 호출 시점을 단정하지 말고 호출하는 쪽의 순서와 인자도 함께 읽어야 해요.', '이 도우미 자체에는 실제 사용자 복사를 하는 명령이 없어요. 검사 설정에 따라 각 경로가 빈 구현일 수도 있어요. 접근 전 계측, 실제 데이터 이동, 실제 반환된 미복사 길이를 세 단계로 구별하세요.'], [('copy-out에서 KASAN과 KCSAN 읽기 검사에 전달하는 주소는 무엇인가요?', ['사용자 목적지인 to예요', '커널 원본인 from이에요'], '정답은 두 번째예요. 본문은 check_read(from, n)이에요. 사용자에게 보낼 데이터를 커널에서 꺼내 읽는 쪽을 검사하므로 방향을 먼저 확인하세요.'), ('이 wrapper가 KMSAN에 넣는 left=0은 이미 실제 복사를 완료했다는 증거인가요?', ['아니요. 이 wrapper는 접근 전이며 0은 전달한 인자예요', '네. 실제 복사 성공을 돌려받은 결과예요'], '정답은 첫 번째예요. 코드가 직접 적은 0이지 copy 함수의 반환값을 받은 것이 아니에요. 실제 복사 실행과 성공 여부는 바깥 경로에서 따로 확인해야 해요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_416.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
